{
  "schema": "ai7.evaluation-rewrite.unit-result/1",
  "unitOrdinal": 1,
  "observations": [
    {
      "itemId": "literary-quality",
      "note": "开篇以“识时务者为俊杰”与“不识时务者为圣贤”两句格言对峙，接着写曾本之费力写出这两句话，呈现以格言定调、人物声音先行的文学笔法。",
      "blockOrdinals": [5, 6, 7]
    },
    {
      "itemId": "literary-quality",
      "note": "“丢下毛笔”“撕碎到找不到一个完整的字”“只留下满屋的叹息”等身体动作与细节，把曾本之的心理矛盾藏在白描动作里，支撑编辑评语中撕信、叹气呈现心理、笔墨克制之说。",
      "blockOrdinals": [8, 14]
    },
    {
      "itemId": "literary-quality",
      "note": "“曾侯乙尊盘级”的寿宴评价及“国宝中的国宝”解释，是带个人印记和文化器物感的比喻，支撑文学品质项的高分判断。",
      "blockOrdinals": [10, 11]
    },
    {
      "itemId": "literary-quality",
      "note": "由寿宴操办、弟子身份、八年前警察带走另一弟子到反复重写书信，叙述者议论与人物内心回忆交替，呈夹叙夹议的书卷气。",
      "blockOrdinals": [9, 10, 12, 13, 14]
    },
    {
      "itemId": "literary-quality",
      "note": "本单元推进主要靠写信撕信、寿宴回顾和书信文化轶事，缺少正面人物行动与外部冲突，可对应编辑所指张力更多来自悬念而非人物行动。",
      "blockOrdinals": [8, 9, 14, 15]
    },
    {
      "itemId": "theme-and-context",
      "note": "标题“青铜重器”、“曾侯乙尊盘”“国宝中的国宝”“楚学界泰斗”等把青铜器物、楚学与学术身份嵌入叙事，支撑主题语境项高分。",
      "blockOrdinals": [1, 2, 10, 11]
    },
    {
      "itemId": "theme-and-context",
      "note": "曾本之为楚学界泰斗，郑雄为钟爱弟子兼女婿，八年前另一弟子被警察带走，呈现师承、身份等级与学界伦理、权力交织。",
      "blockOrdinals": [8, 9, 12, 13, 14]
    },
    {
      "itemId": "theme-and-context",
      "note": "郑雄老家“六十五岁做七十小寿”、男做虚岁女做实岁等地方礼俗写得具体，构成地方风俗与文化语境内容。",
      "blockOrdinals": [9, 10]
    },
    {
      "itemId": "theme-and-context",
      "note": "巴黎女子望玫瑰兴叹、东湖花前月下、男人宁送玫瑰不写情书等叙述，涉及手写书信文化衰落与古今中外对照，支撑社会文化主题。",
      "blockOrdinals": [15]
    },
    {
      "itemId": "theme-and-context",
      "note": "书信文化衰落与性别化“时尚尤物”轶事主要通过闲谈式回溯点染，未在当下情节中展开，对应编辑所指社会议题未充分情节化。",
      "blockOrdinals": [15]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "标题、作者、“壹”后以格言开场，再依次引入人物、寿宴、八年前往事和巴黎轶事；时间标记“前些日子”“八年前”“一九九○年代”清楚。",
      "blockOrdinals": [3, 4, 5, 6, 8, 9, 12, 15]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "信息按写信撕信、寿宴操办、弟子身份、八年前带走另一弟子、重写书信困惑逐层释出，收信对象问题逐步显现。",
      "blockOrdinals": [7, 8, 9, 12, 13, 14]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "以“壹”分章，章内留下为何撕信、另一弟子是谁、信写给谁等多重悬念钩子，信件与弟子线索前后呼应。",
      "blockOrdinals": [4, 7, 8, 13, 14]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "推进多为叙述交代和回忆，主要动作限于写信、撕信、寿宴回顾、巴黎轶事，外部情节进展慢，可说明编辑将结构分下调、认为打分偏高。",
      "blockOrdinals": [8, 9, 12, 13, 14, 15]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "从“壹”到寿宴、八年前、巴黎轶事之间跨度大，场景转换靠说明性段落连接，连贯更多依赖信息与悬念而非行动因果。",
      "blockOrdinals": [4, 8, 9, 12, 15]
    },
    {
      "itemId": "chinese-language",
      "note": "“识时务者为俊杰，不识时务者为圣贤”形成对仗，后文又重复这一组句子，显示文白相间、短句有力的语体。",
      "blockOrdinals": [5, 6, 7, 14]
    },
    {
      "itemId": "chinese-language",
      "note": "“文质彬彬”“花前月下”“墨香墨彩”“端庄典雅”“国宝中的国宝”等四字格与雅词密集，支撑语言项中文白相间、节奏统一的高分。",
      "blockOrdinals": [10, 11, 13, 15]
    },
    {
      "itemId": "chinese-language",
      "note": "“宁肯每天上门送一束玫瑰花，也懒得写情书求爱”“比只花两元钱买张彩票就中了大奖还稀罕”等俗白比喻和口语，显示俗语化与轻讽色彩。",
      "blockOrdinals": [15]
    },
    {
      "itemId": "chinese-language",
      "note": "同一段中“时尚尤物”“香榭丽舍”与“两元钱买彩票中大奖”并置，典雅辞汇与俗白表达形成落差，可对应编辑所指语体不齐。",
      "blockOrdinals": [15]
    },
    {
      "itemId": "chinese-language",
      "note": "“这种叹息不像是针对被撕了好几遍的这封信，更像是为了某个人”以对仗递进式短句收束，体现叙述语言节奏与克制。",
      "blockOrdinals": [14]
    },
    {
      "itemId": "chinese-language",
      "note": "“可好可不好”“有福之人”“拗不过安静”等口语，与“曾侯乙尊盘”“楚学界泰斗”等史论、器物词汇同段出现，呈现语体不齐的一面。",
      "blockOrdinals": [9, 10, 11]
    },
    {
      "itemId": "readers-and-market",
      "note": "开篇以格言和撕信悬念进入，但紧接六十五岁小寿、男做虚岁女做实岁、曾侯乙尊盘意义等说明，知识信息偏密，可能抬高普通读者门槛。",
      "blockOrdinals": [5, 6, 8, 9, 10, 11]
    },
    {
      "itemId": "readers-and-market",
      "note": "主要动作限于写信、撕信、寿宴回顾和书信文化轶事，缺少快节奏冲突与场景推进，市场吸引力更多依赖文化悬念而非强情节。",
      "blockOrdinals": [8, 9, 14, 15]
    },
    {
      "itemId": "readers-and-market",
      "note": "撕信、收信人身份困惑、八年前被警察带走的弟子构成悬念钩子，短段落也便于连载与碎片阅读。",
      "blockOrdinals": [7, 8, 12, 13, 14]
    },
    {
      "itemId": "readers-and-market",
      "note": "东湖、曾侯乙尊盘等具体地标与器物增强地域和题材辨识度，但器物知识需要读者具备一定背景，可能构成门槛。",
      "blockOrdinals": [10, 11, 15]
    },
    {
      "itemId": "readers-and-market",
      "note": "一九九○年代巴黎与东湖书信轶事偏怀旧铺陈，节奏较缓；可支持编辑对市场项“依据不足”而下调至低分的判断。",
      "blockOrdinals": [15]
    },
    {
      "itemId": "readers-and-market",
      "note": "标题“蟠虺”“《青铜重器》之一”“刘醒龙”与“壹”章标记，暗示文化悬疑、长篇连载定位，但开篇未直接给出市场化的强冲突。",
      "blockOrdinals": [1, 2, 3, 4]
    }
  ]
}

{
  "schema": "ai7.evaluation-rewrite.unit-result/1",
  "unitOrdinal": 3,
  "observations": [
    {
      "itemId": "literary-quality",
      "note": "块1以蚌壳水漂“弧线”作喻，并把曾侯乙大墓发掘经验带入景物，比喻与个人记忆相扣，支持编辑评语所说比喻带个人印记，是该项得较高分的依据。",
      "blockOrdinals": [1]
    },
    {
      "itemId": "literary-quality",
      "note": "块2“清水幽幽的那种静，柳枝悠悠的那种软”等句以排比、拟人写湖景与春风，语言有韵律和诗性，支撑文学品质得分。",
      "blockOrdinals": [2]
    },
    {
      "itemId": "literary-quality",
      "note": "块6至9邮递员问话、曾本之“惊讶地回头”“亮身份证”等身体动作与简短对白，呈现人物错愕与克制，符合白描呈现心理的特点。",
      "blockOrdinals": [6, 7, 8, 9]
    },
    {
      "itemId": "literary-quality",
      "note": "块11至16从忍俊不禁、拆信到看出字迹气韵熟悉，靠动作和细节推进心理变化，叙述者少直接解释，支撑作者声音克制有辨识度。",
      "blockOrdinals": [11, 12, 13, 14, 15, 16]
    },
    {
      "itemId": "literary-quality",
      "note": "块2大段湖景与梦境抒情占绝对篇幅，真正冲突靠甲骨文来信的悬念引出，人物主动行动不足，支持编辑指出的议论抒情偏多、张力偏悬念的不足。",
      "blockOrdinals": [2]
    },
    {
      "itemId": "theme-and-context",
      "note": "块2、3把青铜重器、甲骨文、龟甲片化为反复造访的梦境，真实学术材料嵌入人物日常心理，支撑题材底色独特与主题有分量。",
      "blockOrdinals": [2, 3]
    },
    {
      "itemId": "theme-and-context",
      "note": "块10通过东亭邮局老邮递员之口写文化单位多、古怪信件多，块11的旧得发黄信笺带出传统书信文化氛围，契合主题评语中的书信文化议题。",
      "blockOrdinals": [10, 11]
    },
    {
      "itemId": "theme-and-context",
      "note": "块18借曾本之解释邮政法的通信自由与隐私权，把现代法治话题放在日常送信场景中，属于以对话点染社会议题，支持编辑所指部分议题未在情节层面充分展开。",
      "blockOrdinals": [18]
    },
    {
      "itemId": "theme-and-context",
      "note": "块1提到随州擂鼓墩曾侯乙大墓，块2落到东湖碧水，真实考古与武汉地标使地域和学术语境具体，是该项得较高分的依据。",
      "blockOrdinals": [1, 2]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "块2由湖景入梦，块3交代甲骨文梦境周期性造访，块4至5回到现实，块6邮递员出现，信息按梦境—现实—来信逐层递进，支撑单元内推进清楚、线索连贯。",
      "blockOrdinals": [2, 3, 4, 5, 6]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "块6至9用“你是不是姓曾”“你叫曾本之吗”等问答引入信件，块10再由邮递员大段说明古怪信，推进主要依赖对话释放信息。",
      "blockOrdinals": [6, 7, 8, 9, 10]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "块11至16的核心动作只是接信、拆信、看字、认出甲骨文，情节进展集中在信息揭示，外部行动与正面冲突不足，支持编辑下调结构分。",
      "blockOrdinals": [11, 12, 13, 14, 15, 16]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "块18至19以曾本之解释邮政法、邮递员嘟哝“睁眼瞎”收束，留下冲突余波作悬念钩子，但并没有推动场景外移，章末张力仍靠对话。",
      "blockOrdinals": [18, 19]
    },
    {
      "itemId": "structure-and-coherence",
      "note": "块2、3的甲骨文梦境与块15、16认出甲骨文信件前后呼应，信件线索承接紧密，是结构连贯的可记优点。",
      "blockOrdinals": [2, 3, 15, 16]
    },
    {
      "itemId": "chinese-language",
      "note": "块2“清水幽幽的那种静，柳枝悠悠的那种软，还有内心深处的那种空荡荡”用排比与四字格形成统一节奏，支撑文白相间、语体节奏较好的评语。",
      "blockOrdinals": [2]
    },
    {
      "itemId": "chinese-language",
      "note": "块2“像淘气的小猫那样，追着自己的尾巴转了一圈又一圈”为俗白比喻，与前后典雅湖景辞汇并置，显出口语与文雅之间的落差。",
      "blockOrdinals": [2]
    },
    {
      "itemId": "chinese-language",
      "note": "块1“比女人身上的曲线还要美丽”一类修辞夹在考古回忆与湖景描写中，易引争议，支持编辑所指个别比喻拉低语言分。",
      "blockOrdinals": [1]
    },
    {
      "itemId": "chinese-language",
      "note": "块18“邮政法的核心是确保公民通信自由”等法理表述与“别拿甲骨文吓唬人”等口语评点同段或紧接出现，语体不齐，支持该项未得更高分。",
      "blockOrdinals": [18, 19]
    },
    {
      "itemId": "chinese-language",
      "note": "块6、8、13、16、19的简短口语对白与块2、18的书面化长句交替，形成文白相间的总体面貌。",
      "blockOrdinals": [2, 6, 8, 13, 16, 18, 19]
    },
    {
      "itemId": "readers-and-market",
      "note": "块2用长段湖景、梦境和抒情开场，直到块6才出现邮递员问话，开篇怀旧铺陈较慢，可能劝退快节奏悬疑读者，支持编辑下压市场分。",
      "blockOrdinals": [2, 6]
    },
    {
      "itemId": "readers-and-market",
      "note": "块10至16“古怪地址—旧信笺—甲骨文”构成文化悬疑钩子，短段落和章末余波有连载追读潜力，是该项原初高分所看重的依据。",
      "blockOrdinals": [10, 11, 12, 13, 14, 15, 16]
    },
    {
      "itemId": "readers-and-market",
      "note": "块16、18集中出现“甲骨文”“邮政法”“通信自由”“隐私权”等术语与法理词，抬高普通读者门槛，支持编辑所指术语密集可能劝退读者。",
      "blockOrdinals": [16, 18]
    },
    {
      "itemId": "readers-and-market",
      "note": "块2、3的东湖碧水与甲骨文梦境带来地域和题材亲近感，但本单元主要动作仍限于做梦、收信、拆信和问答，缺外部场景推进，支持市场分不高。",
      "blockOrdinals": [2, 3, 6, 7, 8, 9, 10, 11]
    },
    {
      "itemId": "readers-and-market",
      "note": "块19邮递员嘟哝“别拿甲骨文吓唬人”为章末留下口角余波，有轻喜和悬念感，但未形成更大情节推进。",
      "blockOrdinals": [19]
    }
  ]
}
